  <style>
    /* ========== RESET & BASE ========== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg-primary: #0A0A0A;
      --bg-secondary: #111111;
      --bg-card: #161616;
      --bg-card-hover: #1C1C1C;
      --text-primary: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent-blue: #4A90FF;
      --accent-blue-hover: #6AABFF;
      --accent-amber: #E8A838;
      --accent-amber-hover: #F0BC60;
      --border-color: #222222;
      --border-light: #2A2A2A;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --transition: 0.3s ease;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; color: inherit; }
    img { display: block; max-width: 100%; }
    ul { list-style: none; }

    .container { max-width: 1320px; margin: 0 auto; padding: 0 24px; }

    /* ========== NAVIGATION ========== */
    .nav {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border-color);
    }

    .nav-inner {
      max-width: 1320px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 24px; height: 72px;
    }

    .nav-logo {
      font-size: 1.35rem; font-weight: 800; letter-spacing: -0.5px;
      display: flex; align-items: center; gap: 8px;
    }

    .nav-logo span { color: var(--accent-blue); }

    .nav-links { display: flex; align-items: center; gap: 32px; }

    .nav-links a {
      font-size: 0.875rem; font-weight: 500; color: var(--text-secondary);
      transition: color var(--transition); position: relative;
    }

    .nav-links a:hover { color: var(--text-primary); }

    .nav-links a::after {
      content: ''; position: absolute; bottom: -4px; left: 0;
      width: 0; height: 1.5px; background: var(--accent-blue);
      transition: width var(--transition);
    }

    .nav-links a:hover::after { width: 100%; }

    .nav-right { display: flex; align-items: center; gap: 20px; }

    /* Language Selector */
    .lang-selector { position: relative; }

    .lang-toggle {
      display: flex; align-items: center; gap: 6px;
      font-size: 0.8rem; font-weight: 500; color: var(--text-secondary);
      padding: 6px 12px; border: 1px solid var(--border-color);
      border-radius: var(--radius-sm); transition: all var(--transition);
    }

    .lang-toggle:hover { border-color: var(--text-muted); color: var(--text-primary); }

    .lang-toggle svg { width: 14px; height: 14px; transition: transform var(--transition); }

    .lang-selector.open .lang-toggle svg { transform: rotate(180deg); }

    .lang-dropdown {
      position: absolute; top: calc(100% + 8px); right: 0;
      background: var(--bg-card); border: 1px solid var(--border-color);
      border-radius: var(--radius-md); min-width: 180px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all var(--transition); overflow: hidden;
      box-shadow: 0 12px 40px rgba(0,0,0,0.5);
    }

    .lang-selector.open .lang-dropdown {
      opacity: 1; visibility: visible; transform: translateY(0);
    }

    .lang-dropdown button {
      display: flex; align-items: center; gap: 10px;
      width: 100%; padding: 12px 16px;
      font-size: 0.85rem; color: var(--text-secondary);
      transition: all var(--transition);
    }

    .lang-dropdown button:hover { background: var(--bg-card-hover); color: var(--text-primary); }
    .lang-dropdown button.active { color: var(--accent-blue); }

    .lang-dropdown button .lang-code {
      font-weight: 600; color: var(--text-muted); min-width: 24px;
    }

    /* Mobile menu toggle */
    .nav-hamburger {
      display: none; flex-direction: column; gap: 5px;
      padding: 4px; cursor: pointer;
    }

    .nav-hamburger span {
      display: block; width: 22px; height: 2px;
      background: var(--text-primary); border-radius: 2px;
      transition: all var(--transition);
    }

    .nav-hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .nav-hamburger.active span:nth-child(2) { opacity: 0; }
    .nav-hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile nav */
    .mobile-nav {
      display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
      background: var(--bg-primary); z-index: 999; padding: 32px 24px;
      flex-direction: column; gap: 0;
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      display: block; padding: 16px 0;
      font-size: 1.25rem; font-weight: 500; color: var(--text-secondary);
      border-bottom: 1px solid var(--border-color);
      transition: color var(--transition);
    }

    .mobile-nav a:hover { color: var(--text-primary); }

    .mobile-nav .mobile-lang {
      margin-top: 24px; display: flex; gap: 12px;
    }

    .mobile-nav .mobile-lang button {
      padding: 8px 16px; border: 1px solid var(--border-color);
      border-radius: var(--radius-sm); font-size: 0.85rem;
      color: var(--text-secondary); transition: all var(--transition);
    }

    .mobile-nav .mobile-lang button:hover,
    .mobile-nav .mobile-lang button.active { border-color: var(--accent-blue); color: var(--accent-blue); }

    /* ========== HERO CAROUSEL ========== */
    .hero {
      position: relative; min-height: 100vh;
      display: flex; align-items: center;
      padding-top: 72px; overflow: hidden;
    }

    .hero-slides { position: relative; width: 100%; height: calc(100vh - 72px); }

    .hero-slide {
      position: absolute; inset: 0;
      display: flex; align-items: center;
      opacity: 0; visibility: hidden;
      transition: opacity 0.8s ease, visibility 0.8s ease;
    }

    .hero-slide.active { opacity: 1; visibility: visible; }

    .hero-slide-bg {
      position: absolute; inset: 0;
      background-size: cover; background-position: center;
      filter: brightness(0.3);
    }

    .hero-slide-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(10,10,10,0.9) 0%, rgba(10,10,10,0.5) 100%);
    }

    .hero-slide-content {
      position: relative; z-index: 2;
      max-width: 1320px; margin: 0 auto; padding: 0 24px;
      width: 100%;
    }

    .hero-tag {
      display: inline-flex; align-items: center; gap: 8px;
      padding: 6px 14px; border: 1px solid var(--border-light);
      border-radius: 100px; font-size: 0.75rem; font-weight: 600;
      text-transform: uppercase; letter-spacing: 1.5px;
      color: var(--accent-blue); margin-bottom: 24px;
    }

    .hero-tag-dot {
      width: 6px; height: 6px; border-radius: 50%;
      background: var(--accent-blue); animation: pulse-dot 2s ease infinite;
    }

    @keyframes pulse-dot {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .hero-title {
      font-size: clamp(2.2rem, 5vw, 4rem);
      font-weight: 800; line-height: 1.1;
      letter-spacing: -1.5px; margin-bottom: 20px;
      max-width: 700px;
    }

    .hero-desc {
      font-size: clamp(1rem, 1.5vw, 1.2rem);
      color: var(--text-secondary); line-height: 1.6;
      max-width: 560px; margin-bottom: 36px;
    }

    .hero-cta {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 14px 32px; background: var(--accent-blue);
      color: #fff; font-weight: 600; font-size: 0.95rem;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .hero-cta:hover { background: var(--accent-blue-hover); transform: translateY(-1px); }

    .hero-cta svg { width: 16px; height: 16px; }

    /* Hero navigation */
    .hero-nav {
      position: absolute; bottom: 48px; left: 50%;
      transform: translateX(-50%); z-index: 10;
      display: flex; align-items: center; gap: 16px;
    }

    .hero-nav-btn {
      width: 44px; height: 44px; display: flex;
      align-items: center; justify-content: center;
      border: 1px solid var(--border-light); border-radius: 50%;
      transition: all var(--transition); color: var(--text-secondary);
    }

    .hero-nav-btn:hover { border-color: var(--text-primary); color: var(--text-primary); }

    .hero-nav-btn svg { width: 18px; height: 18px; }

    .hero-dots { display: flex; gap: 8px; }

    .hero-dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: var(--text-muted); cursor: pointer;
      transition: all var(--transition);
    }

    .hero-dot.active { background: var(--accent-blue); width: 24px; border-radius: 4px; }

    .hero-counter {
      font-size: 0.8rem; color: var(--text-muted);
      font-variant-numeric: tabular-nums; font-weight: 500;
    }

    /* ========== SECTION HEADERS ========== */
    .section { padding: 120px 0; }

    .section-header { margin-bottom: 64px; }

    .section-label {
      font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
      letter-spacing: 2px; color: var(--accent-blue); margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(2rem, 4vw, 3.2rem);
      font-weight: 800; letter-spacing: -1px;
      line-height: 1.15; margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: clamp(1rem, 1.3vw, 1.15rem);
      color: var(--text-secondary); line-height: 1.6;
      max-width: 640px;
    }

    /* ========== TEAM CAROUSEL ========== */
    .team-section {
      padding: 120px 0;
      background: linear-gradient(180deg, var(--bg-primary) 0%, var(--bg-secondary) 50%, var(--bg-primary) 100%);
    }

    .team-region-tabs {
      display: flex; gap: 8px; margin-bottom: 48px;
      flex-wrap: wrap;
    }

    .region-tab {
      padding: 10px 24px; font-size: 0.875rem; font-weight: 600;
      border: 1px solid var(--border-color); border-radius: 100px;
      color: var(--text-secondary); transition: all var(--transition);
    }

    .region-tab:hover { border-color: var(--text-muted); color: var(--text-primary); }

    .region-tab.active {
      background: var(--accent-blue); border-color: var(--accent-blue);
      color: #fff;
    }

    .team-carousel-wrapper { position: relative; overflow: hidden; }

    .team-carousel {
      display: flex; gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
      cursor: grab;
    }

    .team-carousel.dragging { cursor: grabbing; transition: none; }

    .team-card {
      min-width: 340px; max-width: 340px;
      background: var(--bg-card); border: 1px solid var(--border-color);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: all var(--transition); flex-shrink: 0;
    }

    .team-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 60px rgba(0,0,0,0.4);
    }

    .team-card-photo {
      width: 100%; height: 220px;
      background: var(--bg-card-hover); position: relative; overflow: hidden;
    }

    .team-card-photo-placeholder {
      width: 100%; height: 100%;
      display: flex; align-items: center; justify-content: center;
      font-size: 3rem; font-weight: 700;
      color: var(--text-muted); background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
    }

    .team-card-body { padding: 24px; }

    .team-card-name {
      font-size: 1.1rem; font-weight: 700; margin-bottom: 4px;
    }

    .team-card-title {
      font-size: 0.85rem; color: var(--accent-blue); font-weight: 500;
      margin-bottom: 16px;
    }

    .team-card-quote {
      font-size: 0.9rem; color: var(--text-secondary);
      line-height: 1.6; margin-bottom: 20px;
      font-style: italic; position: relative;
      padding-left: 16px;
      border-left: 2px solid var(--accent-blue);
    }

    .team-card-footer {
      display: flex; align-items: center; justify-content: space-between;
    }

    .team-card-office {
      font-size: 0.8rem; color: var(--text-muted); font-weight: 500;
    }

    .team-card-cta {
      font-size: 0.8rem; font-weight: 600; color: var(--accent-blue);
      transition: color var(--transition);
    }

    .team-card-cta:hover { color: var(--accent-blue-hover); }

    .team-carousel-nav {
      display: flex; align-items: center; justify-content: center;
      gap: 16px; margin-top: 40px;
    }

    .team-carousel-btn {
      width: 44px; height: 44px; display: flex;
      align-items: center; justify-content: center;
      border: 1px solid var(--border-color); border-radius: 50%;
      color: var(--text-secondary); transition: all var(--transition);
    }

    .team-carousel-btn:hover { border-color: var(--text-primary); color: var(--text-primary); }

    .team-carousel-btn svg { width: 18px; height: 18px; }

    /* ========== WORK SHOWCASE ========== */
    .work-section { padding: 120px 0; }

    .work-carousel-wrapper { position: relative; overflow: hidden; }

    .work-carousel {
      display: flex; gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
      cursor: grab;
    }

    .work-carousel.dragging { cursor: grabbing; transition: none; }

    .work-card {
      min-width: 420px; max-width: 420px; flex-shrink: 0;
      background: var(--bg-card); border: 1px solid var(--border-color);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: all var(--transition);
    }

    .work-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 60px rgba(0,0,0,0.4);
    }

    .work-card-thumb {
      width: 100%; height: 260px;
      position: relative; overflow: hidden;
    }

    .work-card-thumb-placeholder {
      width: 100%; height: 100%;
      display: flex; align-items: center; justify-content: center;
      font-size: 1rem; font-weight: 600;
      color: var(--text-muted); letter-spacing: 1px;
    }

    .work-card-body { padding: 24px; }

    .work-card-client {
      font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
      letter-spacing: 1.5px; color: var(--accent-blue); margin-bottom: 8px;
    }

    .work-card-title {
      font-size: 1.15rem; font-weight: 700; margin-bottom: 12px;
      line-height: 1.3;
    }

    .work-card-quote {
      font-size: 0.85rem; color: var(--text-secondary);
      line-height: 1.6; margin-bottom: 8px;
      font-style: italic;
    }

    .work-card-attribution {
      font-size: 0.8rem; color: var(--text-muted); font-weight: 500;
    }

    .work-carousel-nav {
      display: flex; align-items: center; justify-content: center;
      gap: 16px; margin-top: 40px;
    }

    .work-carousel-btn {
      width: 44px; height: 44px; display: flex;
      align-items: center; justify-content: center;
      border: 1px solid var(--border-color); border-radius: 50%;
      color: var(--text-secondary); transition: all var(--transition);
    }

    .work-carousel-btn:hover { border-color: var(--text-primary); color: var(--text-primary); }

    .work-carousel-btn svg { width: 18px; height: 18px; }

    /* ========== CTA BANNER ========== */
    .cta-banner {
      padding: 100px 0;
      background: linear-gradient(135deg, #0d1b3e 0%, #0A0A0A 60%);
      border-top: 1px solid var(--border-color);
      border-bottom: 1px solid var(--border-color);
    }

    .cta-banner-inner {
      max-width: 800px; margin: 0 auto; text-align: center;
    }

    .cta-banner-title {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 800; letter-spacing: -1px;
      margin-bottom: 16px;
    }

    .cta-banner-body {
      font-size: 1.1rem; color: var(--text-secondary);
      line-height: 1.7; margin-bottom: 36px;
    }

    .cta-banner-btn {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 16px 40px; background: var(--accent-blue);
      color: #fff; font-weight: 700; font-size: 1rem;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .cta-banner-btn:hover { background: var(--accent-blue-hover); transform: translateY(-2px); }

    .cta-banner-btn svg { width: 18px; height: 18px; }

    /* ========== HOW WE WORK ========== */
    .how-section { padding: 120px 0; }

    .how-inner {
      display: grid; grid-template-columns: 1fr 1fr;
      gap: 80px; align-items: center;
    }

    .how-visual {
      position: relative; height: 400px;
      border-radius: var(--radius-lg); overflow: hidden;
    }

    .how-visual-placeholder {
      width: 100%; height: 100%;
      background: linear-gradient(135deg, #1a1a2e 0%, #0d1b3e 50%, #16213e 100%);
      display: flex; align-items: center; justify-content: center;
      font-size: 4rem; font-weight: 800; color: rgba(74,144,255,0.15);
      letter-spacing: -2px;
    }

    .how-content { }

    .how-title {
      font-size: clamp(2rem, 3.5vw, 2.8rem);
      font-weight: 800; letter-spacing: -1px;
      line-height: 1.15; margin-bottom: 20px;
    }

    .how-body {
      font-size: 1.05rem; color: var(--text-secondary);
      line-height: 1.7; margin-bottom: 36px;
    }

    .how-cta {
      display: inline-flex; align-items: center; gap: 10px;
      padding: 14px 32px; border: 1px solid var(--accent-blue);
      color: var(--accent-blue); font-weight: 600; font-size: 0.95rem;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .how-cta:hover { background: var(--accent-blue); color: #fff; }

    .how-cta svg { width: 16px; height: 16px; }

    /* ========== LATEST INSIGHTS ========== */
    .insights-section {
      padding: 120px 0;
      background: var(--bg-secondary);
    }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }

    .insight-card {
      background: var(--bg-card); border: 1px solid var(--border-color);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: all var(--transition);
    }

    .insight-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
      box-shadow: 0 20px 60px rgba(0,0,0,0.4);
    }

    .insight-card-thumb {
      width: 100%; height: 180px;
      position: relative; overflow: hidden;
    }

    .insight-card-thumb-placeholder {
      width: 100%; height: 100%;
      display: flex; align-items: center; justify-content: center;
    }

    .insight-type-badge {
      position: absolute; top: 12px; left: 12px;
      padding: 4px 12px; border-radius: 100px;
      font-size: 0.7rem; font-weight: 700;
      text-transform: uppercase; letter-spacing: 1px;
    }

    .badge-podcast { background: #6C3FE0; color: #fff; }
    .badge-article { background: #0E7C5F; color: #fff; }
    .badge-report { background: var(--accent-amber); color: #000; }

    .insight-card-body { padding: 20px; }

    .insight-card-title {
      font-size: 1rem; font-weight: 700;
      line-height: 1.4; margin-bottom: 16px;
    }

    .insight-card-cta {
      font-size: 0.85rem; font-weight: 600; color: var(--accent-blue);
      display: inline-flex; align-items: center; gap: 6px;
      transition: color var(--transition);
    }

    .insight-card-cta:hover { color: var(--accent-blue-hover); }

    .insight-card-cta svg { width: 14px; height: 14px; }

    /* ========== PRINCIPLES ========== */
    .principles-section { padding: 120px 0; }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 24px;
    }

    .principle-card {
      padding: 40px; background: var(--bg-card);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-lg);
      transition: all var(--transition);
    }

    .principle-card:hover {
      border-color: var(--border-light);
      transform: translateY(-2px);
    }

    .principle-number {
      font-size: 0.75rem; font-weight: 700;
      color: var(--accent-blue); margin-bottom: 16px;
      letter-spacing: 2px;
    }

    .principle-title {
      font-size: 1.35rem; font-weight: 700;
      margin-bottom: 12px; line-height: 1.3;
    }

    .principle-desc {
      font-size: 0.95rem; color: var(--text-secondary);
      line-height: 1.7;
    }

    /* ========== FOOTER ========== */
    .footer {
      padding: 80px 0 0;
      border-top: 1px solid var(--border-color);
      background: var(--bg-secondary);
    }

    .footer-ctas {
      display: grid; grid-template-columns: 1fr 1fr;
      gap: 24px; margin-bottom: 64px;
    }

    .footer-cta-card {
      padding: 48px; border-radius: var(--radius-lg);
      border: 1px solid var(--border-color);
      transition: all var(--transition);
    }

    .footer-cta-card:hover { border-color: var(--border-light); }

    .footer-cta-text {
      font-size: 1.1rem; color: var(--text-secondary);
      line-height: 1.6; margin-bottom: 24px;
    }

    .footer-cta-btn {
      display: inline-flex; align-items: center; gap: 8px;
      font-size: 0.95rem; font-weight: 700; color: var(--accent-blue);
      transition: color var(--transition);
    }

    .footer-cta-btn:hover { color: var(--accent-blue-hover); }

    .footer-cta-btn svg { width: 16px; height: 16px; }

    .footer-bottom {
      padding: 40px 0;
      border-top: 1px solid var(--border-color);
      display: flex; align-items: center; justify-content: space-between;
      flex-wrap: wrap; gap: 24px;
    }

    .footer-links { display: flex; gap: 24px; flex-wrap: wrap; }

    .footer-links a {
      font-size: 0.85rem; color: var(--text-muted);
      transition: color var(--transition);
    }

    .footer-links a:hover { color: var(--text-primary); }

    .footer-legal {
      font-size: 0.8rem; color: var(--text-muted);
      display: flex; gap: 16px; flex-wrap: wrap;
    }

    .footer-legal a { color: var(--text-muted); transition: color var(--transition); }
    .footer-legal a:hover { color: var(--text-primary); }

    /* ========== COOKIE CONSENT ========== */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0;
      z-index: 2000; background: var(--bg-card);
      border-top: 1px solid var(--border-color);
      padding: 20px 24px;
      transform: translateY(100%);
      transition: transform 0.4s ease;
      box-shadow: 0 -8px 40px rgba(0,0,0,0.5);
    }

    .cookie-banner.visible { transform: translateY(0); }

    .cookie-inner {
      max-width: 1320px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      gap: 24px; flex-wrap: wrap;
    }

    .cookie-text {
      font-size: 0.875rem; color: var(--text-secondary); line-height: 1.6;
      max-width: 600px;
    }

    .cookie-text a { color: var(--accent-blue); text-decoration: underline; }

    .cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

    .cookie-btn {
      padding: 10px 20px; font-size: 0.85rem; font-weight: 600;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .cookie-btn-accept { background: var(--accent-blue); color: #fff; }
    .cookie-btn-accept:hover { background: var(--accent-blue-hover); }

    .cookie-btn-decline { border: 1px solid var(--border-color); color: var(--text-secondary); }
    .cookie-btn-decline:hover { border-color: var(--text-muted); color: var(--text-primary); }

    .cookie-btn-settings { border: 1px solid var(--border-color); color: var(--text-secondary); }
    .cookie-btn-settings:hover { border-color: var(--text-muted); color: var(--text-primary); }

    /* Cookie settings modal */
    .cookie-modal-overlay {
      position: fixed; inset: 0; z-index: 2100;
      background: rgba(0,0,0,0.7);
      display: none; align-items: center; justify-content: center;
      padding: 24px;
    }

    .cookie-modal-overlay.open { display: flex; }

    .cookie-modal {
      background: var(--bg-card); border: 1px solid var(--border-color);
      border-radius: var(--radius-lg); max-width: 520px; width: 100%;
      padding: 32px; max-height: 80vh; overflow-y: auto;
    }

    .cookie-modal h3 {
      font-size: 1.2rem; font-weight: 700; margin-bottom: 8px;
    }

    .cookie-modal p {
      font-size: 0.85rem; color: var(--text-secondary);
      line-height: 1.6; margin-bottom: 24px;
    }

    .cookie-category {
      display: flex; align-items: center; justify-content: space-between;
      padding: 16px 0; border-bottom: 1px solid var(--border-color);
    }

    .cookie-category-info h4 { font-size: 0.9rem; font-weight: 600; margin-bottom: 2px; }
    .cookie-category-info p { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 0; }

    .cookie-toggle {
      position: relative; width: 44px; height: 24px;
      border-radius: 12px; background: var(--text-muted);
      cursor: pointer; transition: background var(--transition);
    }

    .cookie-toggle.active { background: var(--accent-blue); }

    .cookie-toggle::after {
      content: ''; position: absolute; top: 2px; left: 2px;
      width: 20px; height: 20px; border-radius: 50%;
      background: #fff; transition: transform var(--transition);
    }

    .cookie-toggle.active::after { transform: translateX(20px); }

    .cookie-modal-actions {
      display: flex; gap: 12px; margin-top: 24px;
    }

    .cookie-modal-actions button {
      flex: 1; padding: 12px; font-size: 0.85rem; font-weight: 600;
      border-radius: var(--radius-sm); transition: all var(--transition);
    }

    .cookie-save-btn { background: var(--accent-blue); color: #fff; }
    .cookie-save-btn:hover { background: var(--accent-blue-hover); }

    .cookie-cancel-btn { border: 1px solid var(--border-color); color: var(--text-secondary); }
    .cookie-cancel-btn:hover { border-color: var(--text-muted); color: var(--text-primary); }

    /* ========== RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .how-inner { grid-template-columns: 1fr; gap: 48px; }
      .how-visual { height: 280px; }
      .principles-grid { grid-template-columns: repeat(2, 1fr); }
      .work-card { min-width: 360px; max-width: 360px; }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .nav-hamburger { display: flex; }
      .lang-selector { display: none; }

      .section { padding: 80px 0; }
      .team-section { padding: 80px 0; }
      .work-section { padding: 80px 0; }
      .insights-section { padding: 80px 0; }
      .principles-section { padding: 80px 0; }

      .team-card { min-width: 290px; max-width: 290px; }
      .work-card { min-width: 300px; max-width: 300px; }

      .principles-grid { grid-template-columns: 1fr; }

      .footer-ctas { grid-template-columns: 1fr; }

      .hero-nav { bottom: 24px; }

      .cookie-inner { flex-direction: column; text-align: center; }
      .cookie-actions { width: 100%; justify-content: center; flex-wrap: wrap; }

      .insights-grid {
        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
      }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .section { padding: 60px 0; }
      .team-card { min-width: 260px; max-width: 260px; }
      .work-card { min-width: 270px; max-width: 270px; }
    }
  </style>
</head>
